import json,z3
out=[]
def q(name,formula,expected,scope):
 s=z3.Solver();s.set(timeout=10000);s.add(formula);r=str(s.check());assert r==expected,(name,r);out.append(dict(id=name,result=r,expected=expected,smt=s.sexpr(),model=str(s.model()) if r=='sat' else None,scope=scope))
R=z3.DeclareSort('Record');r=z3.Const('r',R);changed=z3.Function('changed',R,z3.BoolSort());listed=z3.Function('listed',R,z3.BoolSort());admitted=z3.Bool('admitted');closure=z3.ForAll([r],z3.Implies(changed(r),listed(r)))
q('arbitrary-record-delta-closure',z3.And(admitted,z3.Implies(admitted,closure),changed(r),z3.Not(listed(r))),'unsat','Assumes faithful typed comparison and exact mutation-selector listing; executable correspondence checked separately.')
S=z3.DeclareSort('State');F=z3.DeclareSort('Field');s=z3.Const('s',S);f=z3.Const('f',F);required=z3.Function('required',R,S,z3.BoolSort());affected=z3.Function('affected',R,F,z3.BoolSort());normal=z3.Function('normal',R,F,S,z3.BoolSort());original=z3.Function('original',R,F,S,z3.BoolSort());blind=z3.Function('blind',R,F,S,z3.BoolSort());stored=z3.Function('stored',R,F,z3.BoolSort());declared=z3.Function('vaultDeclared',R,F,z3.BoolSort());vault=z3.Function('vaultGranted',R,F,S,z3.BoolSort())
fieldLaw=z3.ForAll([r,f,s],z3.Implies(z3.And(required(r,s),affected(r,f)),z3.And(normal(r,f,s),z3.Or(original(r,f,s),blind(r,f,s)),z3.Implies(stored(r,f),z3.And(declared(r,f),vault(r,f,s))))))
base=z3.And(admitted,z3.Implies(admitted,fieldLaw),required(r,s),affected(r,f))
q('association-fields-cannot-bypass-read-or-blind',z3.And(base,z3.Not(original(r,f,s)),z3.Not(blind(r,f,s))),'unsat','Arbitrary affected Record, Field and required state, including auxiliary association Records; not a native proof.')
q('stored-field-needs-present-vault-declaration',z3.And(base,stored(r,f),z3.Not(declared(r,f))),'unsat','Requires faithful actual stored output-Field classification, exact action designation and complete mutations.')
q('stored-field-needs-vault-grant-in-each-required-state',z3.And(base,stored(r,f),declared(r,f),z3.Not(vault(r,f,s))),'unsat','All-state logical obligation; custody/provider execution not modeled.')
weakOwnership,associationChanged,associationReadable=z3.Bools('weakOwnership associationChanged associationReadable')
q('weak-auxiliary-record-exception-countermodel',z3.And(weakOwnership,associationChanged,z3.Not(associationReadable)),'sat','Ownership permission alone is consistent with unreadable changed association Fields.')
beforeGrant,afterGrant=z3.Bools('beforeGrant afterGrant');q('one-state-only-negative-control',z3.And(beforeGrant,z3.Not(afterGrant)),'sat','Checking original only leaves an unpermitted proposed state.')
maskEqual,originalVisible,blindAllowed=z3.Bools('maskEqual originalVisible blindAllowed');q('mask-equality-does-not-supply-original-or-blind',z3.And(maskEqual,z3.Not(originalVisible),z3.Not(blindAllowed)),'sat','Displayed equality is independent from exact permission predicates.')
T=z3.DeclareSort('Type');A=z3.DeclareSort('Action');t,u=z3.Consts('t u',T);a=z3.Const('a',A);isBlind=z3.Function('isBlind',T,A,z3.BoolSort());ordinary=z3.Function('ordinary',T,A,z3.BoolSort());separated=z3.ForAll([t,u,a],z3.Not(z3.And(isBlind(t,a),ordinary(u,a))))
q('global-blind-role-separation',z3.And(separated,isBlind(t,a),ordinary(u,a)),'unsat','Assumes complete original owner profile and exact source action IDs.')
x,y=z3.Ints('beforeMultiplicity afterMultiplicity');removed=z3.If(x>y,x-y,0);added=z3.If(y>x,y-x,0)
q('opaque-endpoint-multiset-conservation',z3.And(x>=0,y>=0,y!=x-removed+added),'unsat','Per signature arithmetic assumes complete role-labelled normalized endpoint inventories. Opaque IDs are not identities.')
q('parallel-addition-not-set-equality',z3.And(x==2,y==3,removed==0,added==1),'sat','Nonempty multiplicity negative control for set-only comparison.')
physicalReplacement=z3.Bool('physicalReplacement');q('equal-logical-multiset-does-not-prove-no-physical-effect',z3.And(x==2,y==2,physicalReplacement),'sat','Opaque physical replacement intent/custody remains a separate native effect-correspondence obligation.')
oldAnchor,newAnchor,retargetPermit=z3.Bools('oldAnchorGranted newAnchorGranted retargetPermit');q('both-retargeting-anchors-required',z3.And(z3.Implies(retargetPermit,z3.And(oldAnchor,newAnchor)),retargetPermit,oldAnchor,z3.Not(newAnchor)),'unsat','Anchor grant shorthand includes listed mutation, exact owner binding and all required state actions.')
C=z3.Datatype('KnownCell');C.declare('Absent');C.declare('Null');C.declare('Present',('payload',z3.IntSort()));C=C.create();q('known-null-and-known-absence-distinct',C.Null==C.Absent,'unsat','Constructor-level semantic distinction; original core null validation and executable comparison need concrete checks.')
createDelete,ownedEmpty,ownerGrant,permit=z3.Bools('createDelete declaredOwnedEmpty ownerGrant permit');q('empty-inventory-create-delete-special-guard',z3.And(createDelete,ownedEmpty,z3.Not(ownerGrant),permit,z3.Implies(permit,z3.Implies(z3.And(createDelete,ownedEmpty),ownerGrant))),'unsat','Preserves conservative declared-ownership contract independently of actual incidence deltas.')
prior,following,limit=z3.Ints('prior following limit');q('shared-operation-ledger-additivity',z3.And(prior>=0,following>=0,limit>=0,prior+following<=limit,prior+following>limit),'unsat','Assumes every modeled action/comparison charge is applied to the same monotone ledger before work; no total CPU/heap theorem.')
q('nonempty-fully-granted-mutation-population',z3.And(changed(r),listed(r),required(r,s),affected(r,f),normal(r,f,s),original(r,f,s),stored(r,f),declared(r,f),vault(r,f,s)),'sat','Concrete nonvacuity population of logical obligations, not executable/native refinement.')
print(json.dumps(dict(status='conditional-multi-target-write-laws',z3=z3.get_version_string(),scope='Conditional arbitrary Record/Field/State logical obligations, multiset arithmetic, source-role separation and monotone budget laws. Assumes faithful source/type/Key/effect comparison, exhaustive mutation/owner profiles, complete comparable cuts and exact all-state grants. No TypeScript/SQL/native refinement, source authentication, crypto/vault execution, physical opaque replacement pairing, current native authority or total CPU/heap theorem.',queries=out),indent=2))
